  ["6f04929d00a7b580"] = { "%s legge la lettera di Sully pagina dopo pagina.", "." },
  ["6f06242f986db9a1"] = { "Non addestro quelli come te, {class}. Trovati il tuo istruttore prima che mi arrabbi.", "." },
  ["6f0670e28b955332"] = { "Dentro questa casetta, sogno di unirmi alle battaglie che infuriano oltre le mura della città. Eppure il dovere mi impone di condividere il mio sapere con chi combatte al posto mio... per ora.", "." },
