  ["6f0910a37e9d7b12"] = { "Pare che abbiamo stanato questo {name}. Ora aiutami a ucciderlo!", "." },
  ["6f0f0f4bc0e5d38b"] = { "Clicca qui per rimuovere gli effetti della resurrezione e riparare tutto l'equipaggiamento", "." },
  ["6f15ab6a92390df8"] = { "Hai davvero eccelso nella conoscenza dell'incantamento. C'è molto altro da imparare, se lo desideri. Parla con Taladan, nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus.", "." },
  ["6f1af704027df1cd"] = { "Ah, vediamo. Sì, ormai saranno quasi cento volte, scommetto!", "." },
  ["6f29101e041a7a1b"] = { "Lasciati inondare dal potere del Capoguerra! Abbeverati della sua forza! Combatti per la gloria dell'⟦Horde=Orda⟧!", "." },
  ["6f2af6ca2d1f0480"] = { "Purtroppo non sei ancora abbastanza forte da sopravvivere nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧, {class}.", "." },
  ["6f2de2f7f512837c"] = { "Cerchi ⟦Kardris Dreamseeker=Kardris Cercasogni⟧. Lei e gli altri sciamani sono nella sala d'ingresso della Thrall's Fortress, nella Valle della Saggezza.", "." },
  ["6f30efa02aebdb81"] = { "<La nube ribollente di fulmini viventi davanti a te sembra crepitare minacciosa mentre ti avvicini. Forse è meglio andarsene. In fretta.>", "." },
  ["6f314f415c188ade"] = { "Vorrei controllare la mia cassetta di sicurezza.", "." },
  ["6f31944e14703c24"] = { "Hai disturbato il mio riposo, {class}. Ora affronta la mia ira!", "." },
  ["6f389aa51d2a6ced"] = { "C'è qualcosa di cui vuoi parlare, {class}... vieni, siediti accanto a me.", "." },
  ["6f45b639bc777601"] = { "Kahil, è stato un grande sforzo. Torna qui e riposati. Ci penserà Narrisha a ripulire.", "." },
  ["6f4c405c204b9957"] = { "Salute, {class}. È il tempo dell'Harvest Festival, un tempo di grande abbondanza e di ricordo. Partecipiamo ai banchetti per celebrare tutto ciò per cui dobbiamo essere grati, e ricordiamo i nostri antenati e gli eroi del passato per ringraziarli dell'eredità che ci hanno lasciato.\n\nTi invito a partecipare al banchetto offerto qui. Offro anche dei fuochi d'artificio per celebrare questo gioioso periodo dell'anno.", "." },
  ["6f4dff8d16a88580"] = { "Ho la carne migliore di Orgrimmar.", "." },
  ["6f5aa93197116f47"] = { "Prendi questa, bestia!", "." },
  ["6f5dad2dae96d1f6"] = { "La sartoria può tornare molto utile. Una volta ho dovuto ricucirmi il braccio.", "." },
  ["6f5e368d1cb14897"] = { "Te lo prometto: la Valle sarà nostra.", "." },
  ["6f60be90f8412be9"] = { "I Ferroscuro credevano che queste tavolette fossero cifrate. Non è affatto un codice: è la lingua dei draghi antichi.", "." },
  ["6f612f738a448cf4"] = { "Assassini... salvate... il... Magistraaa...", "." },
  ["6f61b2ff6d504160"] = { "Come si usa il cannone?", "." },
  ["6f63eaffce97424f"] = { "Con tutti i combattimenti che facciamo, è ovvio che a ⟦Razor Hill=Tranciacolle⟧ c'è un istruttore di ⟦First Aid=Primo Soccorso⟧. Cerca Rawrk dentro la caserma, sul lato est del villaggio.", "." },
  ["6f666d665bc06fae"] = { "Salute, {name}. Che la saggezza di Elune guidi la tua mano e il tuo cuore. Come posso aiutarti oggi?", "." },
  ["6f6bea187a4e868e"] = { "Salute, <cittadino/cittadina>. Se non hai nulla da chiedermi, ti prego di circolare.", "." },
  ["6f707e5907db17ec"] = { "Goditi il resto del soggiorno a Menethil. Non durerà ancora a lungo.", "." },
  ["6f7cac0a7b0875fb"] = { "Come è potuto succedere?", "." },
  ["6f8465a34116c0fc"] = { "Cervelli...", "." },
  ["6f84bab72a9159d8"] = { "Ah, hai proprio l'aria robusta, eh? Forse puoi darmi una mano con una cosa o due. Qui non c'è molto aiuto, a parte qualche apprendista alle prime armi, e loro hanno altro a cui pensare.", "." },
  ["6f9ae0a3a575fe8f"] = { "Ho circa metà dei rifornimenti necessari per passare alle unità veterane.", "." },
  ["6f9b53b47cd502a8"] = { "%s scatena un attacco devastante.", "." },
  ["6f9d017463c27970"] = { "Thuwd ti insegnerà a scuoiare le tue prede. Cercalo alla Kodohide Leatherworkers, nel Varcolargo.", "." },
  ["6f9e2f8c6fa150db"] = { "Rend, figlio di Manonera: capo impotente del clan ⟦Blackrock=Roccianera⟧. Non esiste bastardo più testardo.\n\nAlla fine della Seconda Guerra, Rend e suo fratello Maim fuggirono in cerca di rifugio nella fortezza montana dei ⟦Blackrock Spire=Bastioni di Roccianera⟧. Fu lì che Rend si proclamò Capoguerra del clan ⟦Blackrock=Roccianera⟧ ormai indebolito.", "." },
  ["6fa4caee5a7f7055"] = { "30 secondi all'inizio della battaglia per la ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["6fab26eb50a940c8"] = { "%s tiene davanti a sé la Rune of Escape.", "." },
  ["6fb0204f82abca49"] = { "Hai un talento eccezionale per l'incantamento. Superi le mie capacità di insegnante, temo. Cerca ⟦Kitta Firewind=Kitta Bruciavento⟧ alla ⟦Tower of Azora=Torre di Azora⟧. Ormai solo lei può essere la tua istruttrice.", "." },
  ["6fdb2afb0570a13c"] = { "OZZIE!!!! OH, NOOO!", "." },
  ["6fe6f97f6b7f2ecd"] = { "Sento odore di {race}", "." },
  ["6ff97bee8299db8f"] = { "La gente di ⟦Nighthaven=Nottequieta⟧ sì che sa far festa!", "." },
  ["6ffb04bc0a4f6754"] = { "Gli infedeli saranno costretti a reagire. Orchi, uomini-toro...", "." },
